const slides = [
{section:"OUVERTURE",title:"MedLink DZ",kicker:"PROJET ENTREPRENEURIAL · ALGÉRIE",kind:"cover",content:`
<div class="cover-layout"><div><span class="tag">SANTÉ · COORDINATION · SUIVI</span><h1 class="cover-title">MedLink <span>DZ</span></h1><p class="cover-sub">Mieux coordonner le suivi des patients après une consultation ou une hospitalisation.</p><p class="lead">Une plateforme numérique qui relie le médecin et son patient autour d'un programme de suivi clair, validé et traçable.</p><div class="cover-foot"><span>Équipe projet</span><span>Entrepreneuriat</span><span>2026</span></div></div><div class="cover-visual"><div class="orb"><i class="orb-node n1"></i><i class="orb-node n2"></i><i class="orb-node n3"></i></div><div class="orb-core">M</div></div></div>`},
{section:"IDENTIFICATION DU PROBLÈME",title:"Le parcours ne s'arrête pas à la sortie",kicker:"01 · PROBLÈME",content:`<div class="slide-body cols-2">
<div class="panel reveal"><span class="tag">LE CONSTAT</span><p class="big-quote" style="margin:14px 0 16px">« La consultation se termine. L'accompagnement, lui, continue. »</p><p>Après une hospitalisation, une intervention ou un traitement, le patient doit parfois suivre plusieurs prescriptions, surveiller son état, réaliser des analyses, prendre des rendez-vous et rester en contact avec son médecin.</p><p style="margin-top:12px">Entre deux consultations, il doit garder le fil de son parcours — parfois avec l'aide de ses proches.</p></div>
<div class="panel reveal"><div class="card-title">Un suivi qui se prolonge à domicile</div><div class="steps">
<div class="step"><div class="step-num">01</div><h3>Retour à domicile</h3><p>Retenir les consignes et organiser les premières étapes.</p></div>
<div class="step"><div class="step-num">02</div><h3>Période de traitement</h3><p>Respecter les prescriptions, examens et rendez-vous.</p></div>
<div class="step"><div class="step-num">03</div><h3>Entre deux consultations</h3><p>Signaler une difficulté et savoir qui contacter.</p></div>
<div class="step"><div class="step-num">04</div><h3>Surveillance</h3><p>Poursuivre les contrôles lorsqu'un suivi reste nécessaire.</p></div>
</div></div></div>
<div class="callout footnote">MedLink DZ vise à maintenir un lien organisé entre le patient, son médecin et, si celui-ci l'autorise, les membres de son équipe de suivi.</div>`},
{section:"IDENTIFICATION DU PROBLÈME",title:"Trois difficultés qui se renforcent",kicker:"01 · PROBLÈME",content:`<div class="slide-body cols-2">
<div class="panel reveal"><span class="tag">PROBLÈME IDENTIFIÉ</span><h3>Une coordination difficile à maintenir à domicile</h3><p>Les actions du suivi — prescriptions, rendez-vous, examens, informations sur l'évolution et demandes d'aide — peuvent être réparties entre plusieurs supports et interlocuteurs.</p><div class="divider"></div><ul>
<li>Consignes réparties entre appels, messages et documents papier.</li>
<li>Patient incertain du professionnel à contacter.</li>
<li>Proches aidants manquant parfois de visibilité sur les étapes à accomplir.</li>
<li>Médecin ne recevant pas toujours facilement les informations utiles entre les consultations.</li>
<li>Recherche d'un professionnel ou d'une clinique disponible et proche parfois longue.</li>
</ul></div>
<div class="panel reveal"><span class="tag">CONTEXTE ALGÉRIEN</span><h3>Un problème à vérifier sur le terrain</h3><p>Le projet part d'une difficulté concrète d'organisation du suivi à domicile et de mise en relation. Il ne suppose ni que tous les patients rencontrent les mêmes obstacles, ni que le système de santé est dépourvu de suivi.</p><div class="divider"></div><p><b>Validation nécessaire :</b> confronter ces hypothèses aux expériences de patients, de familles, de médecins et de structures de santé.</p></div>
</div>
<div class="panel reveal" style="margin-top:13px"><span class="eyebrow">PROBLÉMATIQUE CENTRALE</span><p class="big-quote" style="margin:10px 0 0;font-size:clamp(17px,1.8vw,25px)">Comment assurer, en Algérie, un suivi médical plus continu et mieux coordonné à domicile, en facilitant les échanges avec le médecin sans remplacer son jugement médical ?</p></div>`},
{section:"IDENTIFICATION DU PROBLÈME",title:"Les conséquences possibles",kicker:"01 · PROBLÈME",content:`<div class="slide-body cols-3">
<div class="panel reveal"><span class="tag">CIBLE PRINCIPALE</span><h3>Patients vivant en Algérie</h3><p>Personnes qui rentrent à domicile après une hospitalisation ou suivent un traitement nécessitant un suivi régulier entre les consultations.</p><div class="divider"></div><b class="accent">Profils prioritaires</b><ul>
<li><b>Post-hospitalisation / post-opératoire :</b> consignes, contrôles et organisation de soins à domicile.</li>
<li><b>Maladies chroniques :</b> rendez-vous, examens et échanges réguliers avec le médecin.</li>
<li><b>Après traitement :</b> surveillance et contrôles médicaux encore prévus.</li>
</ul></div>
<div class="panel reveal"><span class="tag">UTILISATEURS SECONDAIRES</span><h3>Proches aidants</h3><p>Membres de la famille ou aidants autorisés par le patient, qui participent à l'organisation pratique du parcours.</p><div class="divider"></div><b class="accent">Leur rôle</b><ul>
<li>Aider à organiser les rendez-vous.</li>
<li>Faciliter les déplacements et démarches.</li>
<li>Suivre les rappels et les étapes prévues.</li>
<li>Contribuer aux échanges dans les limites d'accès autorisées par le patient.</li>
</ul></div>
<div class="panel reveal"><span class="tag">PARTENAIRES PROFESSIONNELS</span><h3>Acteurs du suivi</h3><p>Professionnels et structures qui acceptent de participer à la coordination via la plateforme.</p><div class="divider"></div><b class="accent">Partenaires visés</b><ul>
<li>Médecins traitants et spécialistes.</li>
<li>Assistants médicaux et membres autorisés de l'équipe.</li>
<li>Cabinets médicaux et cliniques.</li>
<li>Services de santé concernés par le suivi à domicile.</li>
</ul></div>
</div>
<div class="callout footnote">Le patient reste au centre du parcours ; les proches n'accèdent aux informations qu'avec une autorisation appropriée.</div>`},
{section:"IDENTIFICATION DU PROBLÈME",title:"Le problème à résoudre",kicker:"01 · PROBLÈME",content:`<div class="slide-body cols-3">
<div class="panel reveal"><span class="tag">LA PLATEFORME FACILITE</span><h3>Organiser et retrouver l'information</h3><ul>
<li>Appels et messages entre patient et professionnels.</li>
<li>Prise et organisation des rendez-vous.</li>
<li>Rappels et suivi des échéances.</li>
<li>Centralisation des informations communiquées.</li>
<li>Suivi des analyses et prescriptions déclarées.</li>
<li>Recherche de médecins et de cliniques à proximité.</li>
</ul></div>
<div class="panel reveal"><span class="tag">L'ASSISTANT IA PEUT</span><h3>Accompagner les étapes prévues</h3><ul>
<li>Rappeler les étapes du programme validé par le médecin.</li>
<li>Expliquer ou reformuler les consignes déjà définies.</li>
<li>Recueillir les informations prévues dans le suivi.</li>
<li>Signaler une demande hors cadre ou nécessitant un contact humain.</li>
<li>Transmettre les éléments utiles au professionnel selon les règles établies.</li>
</ul></div>
<div class="panel reveal"><span class="tag">LA PLATEFORME NE DOIT PAS</span><h3>Se substituer au professionnel</h3><ul>
<li>Poser un diagnostic.</li>
<li>Prescrire ou modifier un traitement.</li>
<li>Interpréter seule des résultats médicaux.</li>
<li>Décider d'une conduite clinique.</li>
<li>Retarder le recours aux services d'urgence.</li>
</ul><p style="margin-top:12px"><b class="gold">Toute décision clinique relève d'un professionnel habilité.</b></p></div>
</div>
<div class="panel reveal" style="margin-top:13px"><div class="card-title">Formulation orale — à retenir</div><p class="big-quote" style="font-size:clamp(14px,1.35vw,18px);margin:0">« Une fois rentré chez lui, le patient doit continuer à suivre ses consignes médicales, mais la coordination entre lui, sa famille et les professionnels peut devenir difficile. MedLink DZ veut maintenir ce lien, centraliser le suivi et faciliter l'accès au bon interlocuteur, au-delà de la consultation. »</p></div>`},
{section:"ÉTUDE DU MARCHÉ",title:"Des signaux confirment l'intérêt du suivi post-hospitalier",kicker:"02 · MARCHÉ",content:`
<div class="slide-body cols-2">
<div class="panel reveal"><span class="tag">UN BESOIN DOCUMENTÉ</span><h3>La période après la sortie est une phase sensible</h3><p>Le patient doit reprendre ses activités, suivre les consignes, organiser les contrôles et savoir quand solliciter l'équipe soignante.</p><div class="divider"></div><p><b>Initiatives universitaires citées dans le dossier :</b></p><ul><li><b>Glyco-Wise :</b> suivi de la glycémie, IoT et apprentissage automatique.</li><li><b>Health Guard :</b> bracelet connecté et biocapteurs pour le suivi en temps réel.</li></ul><p class="note">Ces exemples illustrent des travaux ciblés ; ils ne démontrent pas à eux seuls une offre commerciale disponible à grande échelle.</p></div>
<div class="panel reveal"><span class="tag">UN SIGNAL D'EFFICACITÉ NUMÉRIQUE</span><div class="stat-grid"><div class="stat"><strong>1 885</strong><span>patients dans l'étude publiée en 2022</span></div><div class="stat"><strong>−55%</strong><span>odds de réhospitalisation à 30 jours</span></div><div class="stat"><strong>41%</strong><span>réduction des odds du critère combiné urgences ou réhospitalisation</span></div></div><p style="margin-top:14px">Étude observationnelle à deux centres de soins primaires, avec SMS automatisés et escalade vers l'équipe. Le résultat sur les seules visites aux urgences n'était pas statistiquement significatif.</p><p class="note">JAMA Network Open, 26 octobre 2022. Une étude randomisée ultérieure (2024) n'a pas retrouvé de réduction significative des revisites : l'effet dépend du contexte et du dispositif.</p></div>
</div>
<div class="callout footnote"><b>Contexte algérien :</b> l'APS a rapporté le 11 avril 2026 l'achèvement d'une plateforme nationale de suivi à distance des dossiers médicaux et d'échange entre structures de santé. Cette numérisation institutionnelle ne prouve pas que le suivi quotidien à domicile est déjà couvert : elle souligne l'importance de définir une complémentarité, et non de prétendre remplacer l'existant.</div>`},
{section:"ÉTUDE DU MARCHÉ",title:"Une enquête exploratoire auprès des professionnels de santé",kicker:"02 · MARCHÉ",content:`
<div class="slide-body cols-2"><div class="panel reveal"><span class="tag">QUESTIONNAIRE · 7 QUESTIONS</span><h3>Ce que nous avons cherché à comprendre</h3><ul><li>Fréquence des consultations de suivi après sortie.</li><li>Expériences d'aggravation faute de suivi.</li><li>Canaux de communication à distance utilisés.</li><li>Usage d'applications de rendez-vous.</li><li>Acceptabilité d'un assistant IA limité.</li><li>Crainte principale des professionnels.</li><li>Fonctions et comportements à éviter.</li></ul></div><div class="panel reveal"><span class="tag">LECTURE MÉTHODOLOGIQUE</span><div class="stat-grid"><div class="stat"><strong>7</strong><span>questions déclarées</span></div><div class="stat"><strong>4</strong><span>axes quantifiés dans les résultats transmis</span></div></div><p style="margin-top:14px">Les pourcentages sont repris tels que communiqués dans le dossier de projet.</p><div class="divider"></div><p class="gold"><b>Limite documentaire :</b> le nombre exact de répondants, la date de collecte, le mode de recrutement et les réponses brutes ne sont pas fournis.</p><p>Les résultats décrivent donc uniquement le groupe interrogé ; ils ne peuvent pas être généralisés à l'ensemble des médecins algériens.</p></div></div><div class="callout footnote">Cette enquête exploratoire sert à orienter les choix du MVP. Une validation plus robuste nécessitera un échantillon documenté et des entretiens/tests auprès de médecins et de patients.</div>`},
{section:"ÉTUDE DU MARCHÉ",title:"Le suivi après la sortie reste inégal",kicker:"02 · MARCHÉ",content:`
<div class="slide-body cols-2"><div class="panel reveal"><div class="card-title">Fréquence perçue du suivi après sortie</div><div class="bar-list"><div class="bar-row"><span>Peu</span><div class="bar-track"><div class="bar-fill" data-width="45"></div></div><b class="bar-value">45%</b></div><div class="bar-row"><span>La moitié</span><div class="bar-track"><div class="bar-fill" data-width="35"></div></div><b class="bar-value">35%</b></div><div class="bar-row"><span>Presque tous</span><div class="bar-track"><div class="bar-fill" data-width="15"></div></div><b class="bar-value">15%</b></div><div class="bar-row"><span>Presque aucun</span><div class="bar-track"><div class="bar-fill" data-width="5"></div></div><b class="bar-value">5%</b></div></div></div><div class="panel reveal"><div class="card-title">Aggravation liée au manque de suivi</div><div class="stat-grid"><div class="stat"><strong>50%</strong><span>Souvent</span></div><div class="stat"><strong>45%</strong><span>Parfois</span></div><div class="stat"><strong>5%</strong><span>Jamais</span></div></div><p style="margin-top:18px">Les répondants signalent majoritairement que l'absence de suivi peut coïncider avec une aggravation perçue.</p></div></div><p class="note footnote">Source : enquête fournie par l'équipe. Question et échantillon détaillés non documentés dans les éléments disponibles.</p>`},
{section:"ÉTUDE DU MARCHÉ",title:"Les pratiques actuelles sont peu intégrées",kicker:"02 · MARCHÉ",content:`
<div class="slide-body cols-2"><div class="panel reveal"><div class="card-title">Canaux de suivi à distance déclarés</div><div class="bar-list"><div class="bar-row"><span>Téléphone</span><div class="bar-track"><div class="bar-fill" data-width="55"></div></div><b class="bar-value">55%</b></div><div class="bar-row"><span>WhatsApp</span><div class="bar-track"><div class="bar-fill" data-width="25"></div></div><b class="bar-value">25%</b></div><div class="bar-row"><span>Aucun</span><div class="bar-track"><div class="bar-fill" data-width="15"></div></div><b class="bar-value">15%</b></div><div class="bar-row"><span>SMS</span><div class="bar-track"><div class="bar-fill" data-width="5"></div></div><b class="bar-value">5%</b></div></div></div><div class="panel reveal"><div class="card-title">Utilisation d'une application de rendez-vous</div><div class="metric">100%</div><p class="metric-label">Des répondants déclarent n'utiliser aucun outil de ce type.</p><div class="divider"></div><p>Ce résultat suggère une opportunité d'explorer une solution plus structurée, mais il ne suffit pas à prouver une absence d'offre ou de demande sur le marché.</p></div></div>`},
{section:"ÉTUDE DU MARCHÉ",title:"L'adoption dépend de la confiance",kicker:"02 · MARCHÉ",content:`
<div class="slide-body cols-2"><div class="panel reveal"><div class="card-title">Perception d'un assistant IA</div><div class="bar-list"><div class="bar-row"><span>Très favorable</span><div class="bar-track"><div class="bar-fill" data-width="25"></div></div><b class="bar-value">25%</b></div><div class="bar-row"><span>Sceptique</span><div class="bar-track"><div class="bar-fill" data-width="65"></div></div><b class="bar-value">65%</b></div><div class="bar-row"><span>Opposé</span><div class="bar-track"><div class="bar-fill" data-width="10"></div></div><b class="bar-value">10%</b></div></div></div><div class="panel reveal"><div class="card-title">Principale préoccupation</div><div class="stat-grid"><div class="stat"><strong>65%</strong><span>Responsabilité juridique</span></div><div class="stat"><strong>35%</strong><span>Temps / surcharge</span></div></div><div class="divider"></div><p>La confiance ne se gagne pas par la promesse d'une IA autonome : elle dépend du contrôle du médecin, de la traçabilité et des limites clairement définies.</p></div></div>`},
{section:"ÉTUDE DU MARCHÉ",title:"Les exigences produit ressortent clairement",kicker:"02 · MARCHÉ",content:`
<div class="slide-body cols-2"><div class="panel reveal"><div class="card-title">Trois risques explicitement signalés</div><div class="steps" style="grid-template-columns:1fr"><div class="step"><div class="step-num">01</div><h3>Notifications envahissantes</h3><p>Le médecin doit pouvoir définir les seuils, les horaires et les cas qui méritent une alerte afin de préserver son temps de repos.</p></div><div class="step"><div class="step-num">02</div><h3>Complexité d'utilisation</h3><p>Une interface intuitive est nécessaire pour ne pas ajouter une charge administrative aux professionnels.</p></div><div class="step"><div class="step-num">03</div><h3>Exclusion des patients peu connectés</h3><p>Prévoir des alternatives au tout-numérique : SMS, téléphone ou relais humain, ainsi qu'une prise en compte des langues réellement parlées par les patients.</p></div></div><p class="note">Le questionnaire ne fournit pas de pourcentages pour ces trois réponses : elles sont présentées qualitativement, sans classement chiffré.</p></div><div class="panel reveal"><div class="card-title">Traduction en décisions de conception</div><ul><li>Notifications configurables, regroupées et limitées aux alertes utiles.</li><li>Plages de repos et règles d'escalade paramétrables par le médecin.</li><li>Parcours simple, lisible et accessible sur mobile.</li><li>Relais humain et canaux alternatifs si le patient n'est pas connecté.</li><li>Interface multilingue et collecte adaptée aux usages locaux.</li><li>Assistant limité aux consignes validées et au signalement, sans décision clinique.</li></ul></div></div><div class="callout footnote">L'enquête oriente les priorités de conception. Les exigences devront être confirmées par des tests utilisateurs avec médecins et patients.</div>`},
{section:"CONCURRENCE",title:"Un environnement déjà composé d'acteurs",kicker:"03 · CONCURRENCE",content:`<div class="slide-body cols-3"><div class="panel reveal"><span class="tag">01 · PLATEFORMES DE RENDEZ-VOUS</span><h3>Accéder à un professionnel</h3><div class="pill-list"><span>eTabib</span><span>Yadoc</span><span>ShifaConnect</span><span>Maoudi</span></div><p>Rechercher un professionnel et organiser une consultation.</p></div><div class="panel reveal"><span class="tag">02 · LOGICIELS PROFESSIONNELS</span><h3>Organiser l'activité médicale</h3><div class="pill-list"><span>Symtop</span><span>eTabib Workspace</span><span>agendat.dz</span></div><p>Gérer les agendas, les rendez-vous et certaines tâches administratives.</p></div><div class="panel reveal"><span class="tag">03 · SOLUTIONS INFORMELLES</span><h3>Communiquer et trouver un contact</h3><div class="pill-list"><span>Téléphone</span><span>WhatsApp</span><span>Facebook</span><span>Google Maps</span><span>Bouche-à-oreille</span></div><p>Échanger rapidement, rechercher une adresse ou obtenir une recommandation.</p></div></div><div class="callout footnote"><b>Constat de cadrage :</b> les catégories recensées sont principalement orientées vers l'accès au médecin, la consultation et l'organisation de l'activité. MedLink DZ choisit de se spécialiser dans le suivi structuré du patient à domicile. Les fonctionnalités exactes de chaque acteur doivent être vérifiées individuellement.</div>`},
{section:"CONCURRENCE",title:"Comparer les usages, pas seulement les noms",kicker:"03 · CONCURRENCE",content:`<div class="slide-body cols-2"><div class="panel reveal"><span class="tag">TROIS LIMITES À EXAMINER</span><div class="steps" style="grid-template-columns:1fr"><div class="step"><div class="step-num">01</div><h3>Orientation ponctuelle</h3><p>La priorité de nombreuses solutions recensées est la recherche d'un professionnel, la prise de rendez-vous ou la gestion administrative.</p></div><div class="step"><div class="step-num">02</div><h3>Suivi après traitement</h3><p>Une fois le patient rentré chez lui, la continuité de l'accompagnement peut rester difficile à organiser entre deux consultations.</p></div><div class="step"><div class="step-num">03</div><h3>Suivi médical structuré</h3><p>Les outils généralistes ne sont pas nécessairement conçus autour d'un programme de suivi défini et validé par le médecin.</p></div></div></div><div class="panel reveal"><span class="tag">LE DÉCALAGE IDENTIFIÉ</span><h3>Le rendez-vous ne couvre pas tout le parcours</h3><p>Le patient peut accéder à une consultation, puis manquer d'un accompagnement organisé pendant sa convalescence à domicile.</p><div class="divider"></div><p>Les besoins de suivi — rappels, transmission d'observations, échéances et contact avec le bon interlocuteur — peuvent nécessiter une coordination supplémentaire.</p><div class="divider"></div><p class="big-quote">Notre opportunité : prolonger le suivi au-delà de la consultation.</p></div></div><div class="callout footnote">Cette analyse porte sur les limites possibles des catégories recensées. Elle ne signifie pas que chaque concurrent est dépourvu de fonctions de suivi : les offres et fonctionnalités doivent être vérifiées acteur par acteur.</div>`},
{section:"CONCURRENCE",title:"Le différenciateur visé : la continuité du suivi",kicker:"03 · CONCURRENCE",content:`<div class="slide-body cols-3"><div class="panel reveal"><span class="tag">01 · CONTINUITÉ À DOMICILE</span><h3>Un suivi entre les consultations</h3><p>Un accompagnement organisé après une consultation ou un traitement, dans le cadre défini par le professionnel.</p><ul><li>Le patient transmet ses observations.</li><li>Les consignes et échéances restent accessibles.</li><li>Le contact avec l'équipe soignante est facilité.</li></ul><p class="plan-fit"><b>Avantage :</b> continuité des soins.</p></div><div class="panel reveal plan-featured"><span class="tag">02 · AGENT IA ENCADRÉ</span><h3>Une assistance sous contrôle médical</h3><p>L'agent applique uniquement les consignes d'un protocole défini et validé par le médecin.</p><ul><li>Rappels et collecte d'informations prévues.</li><li>Reformulation des consignes validées.</li><li>Signalement des situations nécessitant une intervention humaine.</li></ul><p class="plan-fit"><b>Avantage :</b> assistance contrôlée.</p><p class="note">Aucun diagnostic, aucune prescription et aucune modification autonome du traitement.</p></div><div class="panel reveal"><span class="tag">03 · RÉSEAU DE PROXIMITÉ</span><h3>Faciliter l'accès au bon interlocuteur</h3><p>Une orientation vers des professionnels et structures de santé proches lorsque le besoin le justifie.</p><ul><li>Recherche de médecins et de cliniques à proximité.</li><li>Facilitation de l'organisation d'une consultation.</li><li>Possibilité de demander une visite à domicile.</li></ul><p class="plan-fit"><b>Avantage :</b> réactivité locale.</p></div></div><div class="callout footnote">La valeur différenciante repose sur la combinaison des trois piliers, au service du patient et du médecin.</div>`},
{section:"CONCURRENCE",title:"La concurrence fixe aussi le niveau d'exigence",kicker:"03 · CONCURRENCE",content:`<div class="slide-body cols-2"><div class="panel reveal"><span class="tag">POUR LES PATIENTS</span><h3>Un parcours plus lisible à domicile</h3><ul><li>Un accompagnement qui se poursuit après le traitement ou la consultation.</li><li>Un contact plus simple avec l'équipe soignante.</li><li>Des consignes et rappels regroupés.</li><li>Une orientation facilitée vers un professionnel lorsque nécessaire.</li></ul><div class="divider"></div><span class="tag">POUR LES MÉDECINS</span><h3>Une meilleure visibilité sur le suivi</h3><ul><li>Une organisation plus structurée des étapes de suivi.</li><li>Des informations regroupées dans un espace sécurisé.</li><li>Des retours patients et alertes à examiner lorsqu'une intervention est nécessaire.</li><li>Une validation médicale conservée à chaque étape sensible.</li></ul></div><div class="panel reveal"><span class="tag">NOTRE POSITIONNEMENT</span><p class="big-quote" style="font-size:clamp(20px,2.2vw,30px)">« Nous ne remplaçons pas la consultation médicale : nous facilitons le suivi entre les consultations. »</p><div class="divider"></div><h3>La promesse MedLink DZ</h3><p>Passer d'une relation principalement organisée autour du rendez-vous à un accompagnement continu, personnalisé et supervisé par le médecin.</p><div class="divider"></div><div class="flow"><div class="flow-item">Consignes validées</div><div class="flow-arrow">→</div><div class="flow-item">Suivi à domicile</div><div class="flow-arrow">→</div><div class="flow-item">Retour au médecin</div></div></div></div>`},
{section:"CONCURRENCE",title:"Synthèse du positionnement",kicker:"03 · CONCURRENCE",content:`<div class="slide-body cols-2"><div class="panel reveal"><div class="card-title">Ce que notre analyse permet d'affirmer</div><ul><li>Le marché comporte déjà des plateformes, des logiciels professionnels et des solutions informelles.</li><li>Ces catégories répondent à des usages différents et ne doivent pas être confondues.</li><li>Les fonctionnalités réelles des concurrents doivent être vérifiées avant toute affirmation d'absence ou de supériorité.</li><li>La confiance, la sécurité et la simplicité conditionnent l'adoption de MedLink DZ.</li></ul></div><div class="panel reveal"><div class="card-title">L'espace que MedLink DZ veut occuper</div><p class="big-quote">Un suivi post-consultation structuré, à domicile, organisé autour des consignes validées par le médecin.</p><div class="divider"></div><div class="pill-list"><span>Continuité</span><span>Assistance encadrée</span><span>Proximité</span><span>Supervision médicale</span></div></div></div>`},
{section:"CONCEPTION DE LA SOLUTION",title:"MedLink DZ : un espace partagé de suivi",kicker:"04 · SOLUTION",content:`
<div class="slide-body cols-2"><div class="panel reveal"><div class="card-title">Promesse fonctionnelle</div><p class="big-quote">Relier le médecin et le patient autour d'un programme de suivi défini, validé et consultable.</p><p>La plateforme organise les étapes après la consultation ou la sortie, sans se substituer au professionnel de santé.</p><div class="pill-list"><span>Patient</span><span>Médecin</span><span>Administration</span><span>Programme de suivi</span></div></div><div class="image-slot reveal" data-image="assets/images/interface.PNG"><div class="placeholder"><span class="placeholder-icon">✧</span><b>INTERFACE PUBLIQUE MEDLINK DZ</b><span>assets/images/interface.PNG</span></div><img alt="Interface d’accueil de MedLink DZ" loading="lazy"></div></div>`},
{section:"CONCEPTION DE LA SOLUTION",title:"Trois espaces, des responsabilités distinctes",kicker:"04 · SOLUTION",content:`
<div class="slide-body cols-3"><div class="panel reveal"><span class="tag">PATIENT</span><h3>Comprendre et suivre</h3><ul><li>Consulter son programme publié</li><li>Accéder aux consignes et documents</li><li>Visualiser les étapes et rappels</li><li>Retrouver les informations utiles</li></ul></div><div class="panel reveal"><span class="tag">MÉDECIN</span><h3>Configurer et contrôler</h3><ul><li>Créer un programme de suivi</li><li>Définir les consignes et échéances</li><li>Vérifier avant publication</li><li>Suivre les patients concernés</li></ul></div><div class="panel reveal"><span class="tag">ADMINISTRATION</span><h3>Superviser la plateforme</h3><ul><li>Gérer les comptes et accès</li><li>Contrôler les éléments de validation</li><li>Assurer le support opérationnel</li><li>Suivre les incidents techniques</li></ul></div></div><div class="image-slot reveal" data-image="assets/images/espacepro.PNG"><div class="placeholder"><span class="placeholder-icon">▥</span><b>ESPACE PROFESSIONNEL</b><span>assets/images/espacepro.PNG</span></div><img alt="Espace professionnel et dépôt des justificatifs MedLink DZ" loading="lazy"></div>`},
{section:"CONCEPTION DE LA SOLUTION",title:"Un parcours construit autour de la validation",kicker:"04 · SOLUTION",content:`
<div class="panel reveal"><div class="steps"><div class="step"><div class="step-num">ÉTAPE 01</div><h3>Consultation</h3><p>Le professionnel identifie les besoins de suivi.</p></div><div class="step"><div class="step-num">ÉTAPE 02</div><h3>Préparation</h3><p>Il configure les consignes, tâches et échéances.</p></div><div class="step"><div class="step-num">ÉTAPE 03</div><h3>Validation</h3><p>Il contrôle le contenu avant toute publication.</p></div><div class="step"><div class="step-num">ÉTAPE 04</div><h3>Suivi patient</h3><p>Le patient consulte le programme et ses rappels.</p></div></div></div><div class="slide-body cols-2" style="margin-top:13px"><div class="panel reveal"><h3>Principe de sécurité fonctionnelle</h3><p>Aucun programme n'est présenté au patient comme validé avant l'action explicite du médecin.</p></div><div class="panel reveal"><h3>Traçabilité recherchée</h3><p>Conserver l'état du programme et les événements utiles pour comprendre ce qui a été publié et quand.</p></div></div>`},
{section:"CONCEPTION DE LA SOLUTION",title:"De l’inscription aux fonctions de suivi",kicker:"04 · SOLUTION",content:`
<div class="slide-body cols-2"><div class="image-slot reveal" data-image="assets/images/inscription.PNG"><div class="placeholder"><span class="placeholder-icon">＋</span><b>INSCRIPTION PATIENT</b><span>assets/images/inscription.PNG</span></div><img alt="Formulaire de création de compte patient MedLink DZ" loading="lazy"></div><div class="image-slot reveal" data-image="assets/images/fonctionnalités.PNG"><div class="placeholder"><span class="placeholder-icon">⚙</span><b>FONCTIONNALITÉS ET NOTIFICATIONS</b><span>assets/images/fonctionnalités.PNG</span></div><img alt="Configuration des préférences de notification MedLink DZ" loading="lazy"></div></div><div class="slide-body cols-2" style="margin-top:12px"><div class="panel reveal"><h3>Côté patient</h3><p>Un point d'accès unique aux consignes publiées, aux étapes et aux informations de suivi.</p></div><div class="panel reveal"><h3>Côté médecin</h3><p>Un espace de préparation, de validation et de consultation des programmes associés aux patients.</p></div></div>`},
{section:"CONCEPTION DE LA SOLUTION",title:"Architecture technique et garde-fous",kicker:"04 · SOLUTION",content:`
<div class="slide-body cols-2"><div class="image-slot reveal" data-image="assets/images/IMG1.jpg"><div class="placeholder"><span class="placeholder-icon">▧</span><b>VISUEL COMPLÉMENTAIRE DU PROJET</b><span>assets/images/IMG1.jpg</span></div><img alt="Visuel complémentaire du projet MedLink DZ" loading="lazy"></div><div class="panel reveal"><div class="card-title">Socle technique prévu</div><div class="pill-list"><span>Next.js</span><span>API Routes</span><span>Supabase Auth</span><span>PostgreSQL</span><span>RLS</span><span>Realtime</span><span>pg_cron</span><span>Vercel</span></div><div class="divider"></div><p><b class="accent">Sécurité :</b> authentification, séparation des rôles et politiques d'accès aux données.</p><p><b class="accent">Contrôle :</b> le contenu médical publié reste sous responsabilité et validation du médecin.</p></div></div><div class="callout footnote">Les choix d'hébergement et de traitement des données de santé doivent être validés juridiquement et techniquement avant ouverture au public.</div>`},
{section:"MODÈLE ÉCONOMIQUE",title:"Un modèle B2B par abonnement professionnel",kicker:"05 · BUSINESS MODEL",content:`
<div class="slide-body cols-3 plan-grid">
<div class="panel reveal plan-card">
<span class="tag">ESSENTIEL · SUIVI MANUEL</span><div class="metric">2 500 <small style="font-size:13px">DA</small></div><div class="metric-label">par professionnel / mois</div><div class="divider"></div>
<h3>Le médecin organise et pilote chaque étape.</h3>
<div class="plan-section"><b>Gestion du cabinet et des patients</b><ul><li>Espace professionnel avec liste et fiches patients</li><li>Centralisation des informations utiles au suivi</li><li>Gestion des rendez-vous et demandes de visites à domicile</li></ul></div>
<div class="plan-section"><b>Programme de suivi manuel</b><ul><li>Création des consignes, tâches et étapes par le médecin</li><li>Définition des dates, fréquences et échéances quotidiennes ou hebdomadaires</li><li>Modification et publication après validation explicite</li><li>Suivi manuel de l'avancement des tâches</li></ul></div>
<div class="plan-section"><b>Communication et rappels</b><ul><li>Messagerie et historique des échanges</li><li>Notifications dans l'application et rappels par SMS</li><li>Relance et reprise de contact à l'initiative du professionnel</li><li>SMS pour les patients sans connexion Internet, selon le quota du forfait</li></ul></div>
<p class="plan-fit"><b>Idéal pour :</b> les médecins qui veulent un outil structuré, tout en conservant la gestion directe du suivi.</p>
</div>
<div class="panel reveal plan-card plan-featured">
<span class="tag">ASSISTÉ · INTELLIGENCE ARTIFICIELLE</span><div class="metric">5 000 <small style="font-size:13px">DA</small></div><div class="metric-label">par professionnel / mois</div><div class="divider"></div>
<h3>L'IA prépare et facilite. Le médecin décide.</h3>
<div class="plan-section"><b>Tout le contenu du plan Essentiel</b><ul><li>Gestion des patients, rendez-vous et visites à domicile</li><li>Programmes manuels possibles à tout moment</li><li>Notifications dans l'application et rappels par SMS</li></ul></div>
<div class="plan-section"><b>Préparation assistée par IA</b><ul><li>Génération d'une première ébauche de programme à partir des instructions écrites du médecin</li><li>Proposition de tâches, fréquences, dates et rappels</li><li>Révision et ajustement par le médecin avant publication</li></ul></div>
<div class="plan-section"><b>Assistant patient encadré</b><ul><li>Réponses aux questions simples à partir du programme et des contenus validés</li><li>Rappel et reformulation des consignes déjà publiées</li><li>Identification des demandes hors programme ou ambiguës</li><li>Transmission au médecin avec résumé et contexte</li><li>SMS disponibles pour les patients sans connexion Internet, selon quota</li></ul></div>
<p class="plan-fit"><b>Idéal pour :</b> les médecins qui veulent réduire la saisie répétitive et mieux traiter les demandes courantes, sans déléguer la décision médicale.</p>
</div>
<div class="panel reveal plan-card">
<span class="tag">DÉLÉGUÉ · IA PREMIUM</span><div class="metric">8 000 <small style="font-size:13px">DA</small></div><div class="metric-label">par professionnel / mois</div><div class="divider"></div>
<h3>L'agent exécute le suivi opérationnel selon les règles du médecin.</h3>
<div class="plan-section"><b>Tout le contenu du plan Assisté</b><ul><li>Gestion du cabinet, patients, rendez-vous et visites à domicile</li><li>Programmes assistés ou entièrement manuels</li><li>Assistant patient et rappels SMS</li></ul></div>
<div class="plan-section"><b>Suivi délégué et relances</b><ul><li>Déclenchement de check-ins quotidiens ou hebdomadaires selon le programme validé</li><li>Relances automatiques en cas de tâche non confirmée ou de réponse manquante</li><li>Collecte structurée des retours du patient</li><li>Détection des réponses nécessitant une vérification humaine</li></ul></div>
<div class="plan-section"><b>Supervision et capacité renforcées</b><ul><li>Synthèse périodique de l'avancement et des échanges pour le médecin</li><li>Alertes et escalade des demandes sensibles ou hors périmètre</li><li>Historique des relances, réponses, alertes et interventions</li><li>Capacité prévue pour un volume supérieur de patients et d'interactions simultanées</li><li>SMS disponibles pour les patients sans connexion Internet, selon quota</li></ul></div>
<p class="plan-fit"><b>Idéal pour :</b> les professionnels qui souhaitent déléguer une partie du suivi organisationnel et des relances, tout en gardant le contrôle clinique.</p>
</div>
</div>
<div class="callout footnote">Offres et tarifs proposés, non encore commercialisés. Les quotas mensuels (patients actifs, SMS, interactions IA), conditions de dépassement et coûts variables restent à chiffrer avant lancement. Dans tous les plans, le médecin conserve la responsabilité de la validation médicale ; l'IA ne diagnostique pas, ne prescrit pas et ne modifie pas seule un programme.</div>`},
{section:"MODÈLE ÉCONOMIQUE",title:"La valeur est liée au temps et à l'organisation",kicker:"05 · BUSINESS MODEL",content:`
<div class="slide-body cols-2"><div class="panel reveal"><div class="card-title">Pour le médecin</div><ul><li>Centraliser les programmes de suivi</li><li>Réduire la dispersion des consignes</li><li>Rendre les étapes visibles</li><li>Garder la main sur la validation et la publication</li></ul><div class="divider"></div><p class="note">Le gain de temps doit être mesuré lors d'un pilote, et non présenté comme un résultat déjà démontré.</p></div><div class="panel reveal"><div class="card-title">Pour le patient</div><ul><li>Retrouver les consignes au même endroit</li><li>Comprendre les étapes à venir</li><li>Recevoir des rappels utiles</li><li>Savoir comment reprendre contact</li></ul><div class="divider"></div><p class="note">L'accessibilité doit inclure les patients peu connectés ou peu à l'aise avec le numérique.</p></div></div><div class="callout footnote">Le payeur principal envisagé est le professionnel de santé ; l'accès patient est pensé comme une composante du service.</div>`},
{section:"MODÈLE ÉCONOMIQUE",title:"Des partenaires et des coûts identifiés",kicker:"05 · STRUCTURE DE COÛTS",content:`
<div class="slide-body cols-2"><div class="panel reveal"><div class="card-title">Prestataires et dépenses prévisionnelles</div><div class="table-wrap"><table class="data-table"><thead><tr><th>Domaine</th><th>Prestataire</th><th>Coût</th></tr></thead><tbody><tr><td>IA</td><td>DzTokens</td><td>10 000 DA / mois</td></tr><tr><td>Hébergement</td><td>ISSAL NET · FlexCompute</td><td>17 500 DA HT / mois</td></tr><tr><td>Domaine</td><td>HOSTARTS · DZ + COM</td><td>4 816 DA / an</td></tr><tr><td>Publicité</td><td>Meta Ads + Google Ads</td><td>50 000 DA / mois</td></tr><tr><td>Gestion marketing</td><td>AdsMedia</td><td>35 000 DA / mois</td></tr><tr><td>SMS</td><td>LINKSY · Flex Pro</td><td>12 000 DA / mois</td></tr><tr><td>Appels</td><td>LINKSY ou fournisseur compatible</td><td>Sur devis</td></tr></tbody></table></div></div><div class="panel reveal"><div class="card-title">Budget de fonctionnement</div><div class="metric">124 500 <small style="font-size:14px">DA / mois</small></div><p class="metric-label">Total des six charges mensuelles, hors appels et taxes éventuelles.</p><div class="divider"></div><div class="metric" style="font-size:34px">1 498 816 <small style="font-size:13px">DA / an</small></div><p class="metric-label">1 494 000 DA de charges mensuelles annualisées + 4 816 DA de domaine.</p><p class="note">À confirmer par devis : consommation de tokens IA, volume de SMS, capacité d'hébergement, frais de paiement, taxes et support.</p></div></div><div class="callout footnote">Budget prévisionnel. Les frais d'appels ne sont pas chiffrés et sont exclus des calculs.</div>`},
{section:"MODÈLE ÉCONOMIQUE",title:"50 médecins : un chiffre d'affaires projeté de 230 000 DA",kicker:"05 · REVENUS",content:`
<div class="slide-body cols-2"><div class="panel reveal"><div class="card-title">Répartition des abonnements</div><div class="table-wrap"><table class="data-table"><thead><tr><th>Formule</th><th>Médecins</th><th>Prix / mois</th><th>Revenu</th></tr></thead><tbody><tr><td>Pack Manuel</td><td>20</td><td>2 500 DA</td><td><b>50 000 DA</b></td></tr><tr><td>Pack IA</td><td>20</td><td>5 000 DA</td><td><b>100 000 DA</b></td></tr><tr><td>Pack IA Premium</td><td>10</td><td>8 000 DA</td><td><b>80 000 DA</b></td></tr><tr><td colspan="3"><b>Total · 50 médecins</b></td><td><b class="accent">230 000 DA</b></td></tr></tbody></table></div></div><div class="panel reveal"><div class="card-title">Revenus prévisionnels</div><div class="stat-grid"><div class="stat"><strong>230 000</strong><span>DA / mois</span></div><div class="stat"><strong>2 760 000</strong><span>DA / an</span></div><div class="stat"><strong>4 600</strong><span>DA / médecin / mois · revenu moyen</span></div></div><div class="divider"></div><p>Le revenu moyen est calculé à partir du mix : 230 000 DA ÷ 50 abonnés.</p><p class="note">Scénario cible, pas un portefeuille de clients déjà acquis. Les revenus hors forfait ne sont pas inclus.</p></div></div><div class="callout footnote">Le SMS est prévu dans les trois formules pour les patients sans connexion Internet. Les quotas et dépassements doivent être définis contractuellement.</div>`},
{section:"MODÈLE ÉCONOMIQUE",title:"Un résultat prévisionnel positif à 50 médecins",kicker:"05 · RENTABILITÉ",content:`
<div class="slide-body cols-2"><div class="panel reveal"><div class="card-title">Compte de résultat simplifié</div><div class="table-wrap"><table class="data-table"><tbody><tr><td>Revenus mensuels</td><td><b>230 000 DA</b></td></tr><tr><td>Charges mensuelles</td><td>−124 500 DA</td></tr><tr><td><b>Solde mensuel indicatif</b></td><td><b class="accent">105 500 DA</b></td></tr><tr><td>Revenus annuels</td><td>2 760 000 DA</td></tr><tr><td>Charges annuelles + domaine</td><td>−1 498 816 DA</td></tr><tr><td><b>Résultat annuel estimé</b></td><td><b class="accent">1 261 184 DA</b></td></tr></tbody></table></div><p class="note">Le résultat annuel tient compte du domaine (4 816 DA/an), contrairement au simple calcul 105 500 × 12.</p></div><div class="panel reveal"><div class="card-title">Retour sur investissement prévisionnel</div><div class="metric">84,15%</div><p class="metric-label">ROI = résultat annuel estimé ÷ dépenses annuelles estimées.</p><div class="formula" style="margin-top:18px">1 261 184 ÷ 1 498 816 × 100</div><p style="margin-top:14px">Potentiel de rentabilité si 50 médecins sont abonnés au mix tarifaire prévu et si les charges restent proches du budget.</p></div></div><div class="callout footnote">Projection avant impôts, appels, frais de paiement, coûts variables supplémentaires et dépenses non recensées. Le ROI est un indicateur prévisionnel, pas une garantie de rendement ni un délai de récupération d'un investissement initial.</div>`},
{section:"MODÈLE ÉCONOMIQUE",title:"Le seuil de rentabilité est estimé à 28 médecins",kicker:"05 · SEUIL DE RENTABILITÉ",content:`
<div class="slide-body cols-2"><div class="panel reveal"><div class="card-title">Revenus et charges selon le nombre d'abonnés</div><svg viewBox="0 0 560 320" role="img" aria-label="Courbe des revenus et des coûts mensuels" style="width:100%;height:auto;display:block"><line x1="58" y1="24" x2="58" y2="270" stroke="currentColor" opacity=".45"/><line x1="58" y1="270" x2="530" y2="270" stroke="currentColor" opacity=".45"/><line x1="58" y1="24" x2="530" y2="24" stroke="currentColor" opacity=".12"/><line x1="58" y1="147" x2="530" y2="147" stroke="currentColor" opacity=".12"/><text x="50" y="274" text-anchor="end" font-size="11" fill="currentColor">0</text><text x="50" y="151" text-anchor="end" font-size="11" fill="currentColor">125k</text><text x="50" y="28" text-anchor="end" font-size="11" fill="currentColor">250k</text><text x="58" y="291" text-anchor="middle" font-size="11" fill="currentColor">0</text><text x="152" y="291" text-anchor="middle" font-size="11" fill="currentColor">10</text><text x="247" y="291" text-anchor="middle" font-size="11" fill="currentColor">20</text><text x="341" y="291" text-anchor="middle" font-size="11" fill="currentColor">30</text><text x="436" y="291" text-anchor="middle" font-size="11" fill="currentColor">40</text><text x="530" y="291" text-anchor="middle" font-size="11" fill="currentColor">50</text><text x="294" y="316" text-anchor="middle" font-size="12" fill="currentColor">Nombre de médecins</text><text x="12" y="155" transform="rotate(-90 12 155)" text-anchor="middle" font-size="12" fill="currentColor">Montant (DA)</text><line x1="58" y1="147.5" x2="530" y2="147.5" stroke="#D99A45" stroke-width="3"/><polyline points="58,270 152.4,247.3 246.8,224.7 341.2,202 435.6,179.4 530,43.7" fill="none" stroke="#4D9DE0" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/><line x1="314" y1="147.5" x2="314" y2="270" stroke="#D99A45" stroke-dasharray="4 4" opacity=".8"/><circle cx="314" cy="147.5" r="5" fill="#D99A45"/><rect x="324" y="118" width="150" height="24" rx="6" fill="#D99A45" opacity=".16"/><text x="330" y="134" font-size="11" fill="currentColor">Seuil ≈ 27,1 → 28</text><line x1="360" y1="16" x2="384" y2="16" stroke="#4D9DE0" stroke-width="3"/><text x="390" y="20" font-size="11" fill="currentColor">Revenus</text><line x1="455" y1="16" x2="479" y2="16" stroke="#D99A45" stroke-width="3"/><text x="485" y="20" font-size="11" fill="currentColor">Charges</text></svg><p class="note">Modèle simplifié : revenu moyen constant de 4 600 DA par médecin et charges mensuelles fixes de 124 500 DA.</p></div><div class="panel reveal"><div class="card-title">Calcul du seuil</div><div class="formula">124 500 ÷ 4 600 = 27,07</div><div class="metric" style="margin-top:14px">28 <small style="font-size:14px">médecins</small></div><p class="metric-label">Nombre entier minimal pour couvrir les charges mensuelles.</p><div class="divider"></div><p><b>À 27 médecins :</b> 124 200 DA de revenus, soit −300 DA par rapport aux charges.</p><p><b>À 28 médecins :</b> 128 800 DA de revenus, soit +4 300 DA avant coûts exclus.</p></div></div><div class="callout footnote">Seuil calculé sur le mix moyen des abonnements. Il évoluera selon la répartition des packs et les coûts variables. En intégrant le domaine au prorata mensuel, le seuil reste de 28 médecins.</div>`},{section:"ÉTUDE JURIDIQUE",title:"Choisir une structure adaptée",kicker:"06 · JURIDIQUE",content:`
<div class="slide-body cols-2"><div class="panel reveal"><div class="card-title">Piste étudiée : SARL</div><div class="metric">2–50</div><p class="metric-label">Nombre d'associés indiqué pour la SARL.</p><div class="divider"></div><p>Une équipe de six personnes entre dans cette fourchette. Le capital, la répartition des parts, la gérance et les formalités doivent être définis avec un notaire et le CNRC.</p><p class="note">Référence : article 590 du Code de commerce, modifié par la loi n° 15-20 du 30 décembre 2015.</p></div><div class="panel reveal"><div class="card-title">Démarches à cadrer</div><ul><li>Choisir la dénomination et l'objet social</li><li>Définir les associés et les apports</li><li>Rédiger les statuts</li><li>Effectuer les formalités d'immatriculation</li><li>Organiser la comptabilité et les obligations fiscales</li><li>Évaluer l'éligibilité au label startup</li></ul></div></div><div class="callout footnote">La SARL est une piste de structuration, pas une société déjà constituée ni un avis juridique définitif.</div>`},
{section:"ÉTUDE JURIDIQUE",title:"Le cadre santé et données personnelles",kicker:"06 · JURIDIQUE",content:`
<div class="legal-grid reveal">
<div class="legal-item"><b>Loi n° 18-07 · art. 3, 7, 9 et 18</b><span>Les informations relatives à la santé sont des données sensibles. Le traitement doit respecter le régime applicable à ces données, le consentement exprès ou une exception légale, ainsi que les principes de finalité, pertinence et durée de conservation.</span></div>
<div class="legal-item"><b>Loi n° 18-07 · art. 12 à 14</b><span>Les traitements sont soumis à une formalité préalable auprès de l’ANPDP : déclaration ou autorisation selon la qualification du traitement et les dispositions applicables.</span></div>
<div class="legal-item"><b>Loi n° 25-11 (2025) · art. 41 bis à 41 bis 3</b><span>Ajout du délégué à la protection des données, du registre des activités de traitement et du carnet automatisé retraçant les opérations sur les données.</span></div>
<div class="legal-item"><b>Loi n° 18-11 · art. 23, 24 et 169</b><span>Droit du patient à l’information sur sa santé, respect de la vie privée et du secret médical ; obligation de secret médical et/ou professionnel pour les professionnels de santé.</span></div>
</div>
<div class="panel reveal" style="margin-top:13px"><div class="card-title">Application directe à MedLink DZ</div><p>Les dossiers, programmes de suivi et échanges peuvent contenir des données de santé sensibles. Leur collecte, leur hébergement, leur accès par les médecins, les sous-traitants et les éventuels fournisseurs cloud doivent donc être qualifiés et encadrés avant toute mise en production.</p></div>`},
{section:"ÉTUDE JURIDIQUE",title:"Les garanties à intégrer avant lancement",kicker:"06 · JURIDIQUE",content:`
<div class="slide-body cols-2">
<div class="panel reveal scroll-panel"><div class="card-title">Obligations de traitement et de sécurité</div><ul>
<li><b>Avant collecte :</b> identifier le responsable du traitement, les finalités, les données, les destinataires et la durée de conservation (art. 14).</li>
<li><b>Formalités ANPDP :</b> déterminer le régime de déclaration ou d’autorisation applicable (art. 12 à 18).</li>
<li><b>Information et droits :</b> informer clairement le patient et organiser l’accès, la rectification et l’opposition (art. 32 à 36).</li>
<li><b>Protection technique :</b> contrôle d’accès, chiffrement adapté, sauvegardes, journalisation et gestion des habilitations (art. 38).</li>
<li><b>Gouvernance :</b> registre des traitements et carnet automatisé des opérations (loi 25-11, art. 41 bis 2 et 41 bis 3).</li>
</ul></div>
<div class="panel reveal scroll-panel"><div class="card-title">Responsabilités et prestataires</div><ul>
<li><b>Secret médical :</b> limiter les accès aux personnes habilitées et aux besoins légitimes du suivi (loi 18-11, art. 24 et 169).</li>
<li><b>Contrats :</b> définir les rôles du médecin, de la plateforme et des sous-traitants ; encadrer les accès et la confidentialité.</li>
<li><b>Hébergement :</b> cartographier les pays de stockage et d’accès ; examiner les transferts hors Algérie au regard de l’art. 44.</li>
<li><b>Incidents :</b> prévoir détection, documentation, réponse et notification selon le régime juridique effectivement applicable.</li>
<li><b>Délégué données :</b> analyser l’obligation et organiser sa désignation/coordonnées selon l’art. 41 bis.</li>
</ul></div></div>
<div class="callout footnote">Attention : l’art. 45 bis 6 à 10 ajouté par la loi 25-11 appartient au titre consacré aux traitements à des fins pénales ; son délai de notification de 5 jours ne doit pas être présenté comme une règle générale applicable à MedLink DZ. Le transfert international (art. 44), le régime des données sensibles et les formalités ANPDP doivent être vérifiés sur le cas concret.</div>`},
{section:"ÉTUDE JURIDIQUE",title:"IA encadrée : aucune autonomie clinique",kicker:"06 · JURIDIQUE",content:`
<div class="slide-body cols-2"><div class="panel reveal"><div class="card-title">Périmètre acceptable du prototype</div><ul><li>Retrouver des informations issues du programme validé</li><li>Expliquer les consignes déjà publiées</li><li>Orienter vers le médecin lorsque la demande dépasse le cadre</li><li>Signaler les situations nécessitant un relais humain</li></ul></div><div class="panel reveal"><div class="card-title">Fonctions exclues du périmètre clinique</div><ul><li>Diagnostic autonome</li><li>Prescription ou modification de traitement</li><li>Décision sur une urgence</li><li>Modification autonome du programme médical</li><li>Remplacement du jugement du professionnel</li></ul></div></div><div class="callout footnote">Garde-fou juridique : la loi 18-11, art. 186, sanctionne notamment l’établissement d’un diagnostic ou l’administration d’un traitement par une personne non habilitée. Les limites de l’assistant (pas de diagnostic, prescription ni modification du programme) sont donc un choix de conception essentiel ; toute décision clinique reste réservée au professionnel habilité.</div>`},
{section:"ÉTUDE JURIDIQUE",title:"Conditions de passage au lancement public",kicker:"06 · JURIDIQUE",content:`
<div class="panel reveal"><div class="steps"><div class="step"><div class="step-num">01 · JURIDIQUE</div><h3>Valider le cadre</h3><p>Structure, données de santé, contrats, formalités et obligations applicables.</p></div><div class="step"><div class="step-num">02 · SÉCURITÉ</div><h3>Auditer le produit</h3><p>Contrôle d'accès, tests, sauvegardes, incidents et protection des données.</p></div><div class="step"><div class="step-num">03 · TERRAIN</div><h3>Piloter avec prudence</h3><p>Tester avec des professionnels volontaires et des données adaptées.</p></div><div class="step"><div class="step-num">04 · PUBLIC</div><h3>Ouvrir progressivement</h3><p>Après validation, support, documentation et suivi des indicateurs.</p></div></div></div><div class="callout footnote">Aucune autorisation ministérielle, conformité complète ou labellisation startup n'est présentée comme déjà acquise.</div>`},
{section:"CONCLUSION",title:"Structurer le suivi. Renforcer le lien.",kicker:"MEDLINK DZ · CONCLUSION",kind:"closing",content:`
<div class="cover-visual"><div class="orb"><i class="orb-node n1"></i><i class="orb-node n2"></i><i class="orb-node n3"></i></div><div class="orb-core">M</div></div><span class="tag">UNE PLATEFORME DE COORDINATION</span><h1>MedLink <span class="accent">DZ</span></h1><p class="lead">Un suivi plus clair pour le patient. Un meilleur cadre de coordination pour le médecin. La décision médicale reste humaine.</p><div class="cover-foot" style="justify-content:center"><span>Merci</span><span>Questions & échanges</span></div>`}
];

const stage=document.querySelector("#stage");
const progress=document.querySelector("#progress-fill");
const progressLabel=document.querySelector("#progress-label");
const sectionLabel=document.querySelector("#section-label");
const overview=document.querySelector("#overview");
const overviewGrid=document.querySelector("#overview-grid");
let current=0, locked=false;

function renderSlide(index,animate=true){
  current=Math.max(0,Math.min(slides.length-1,index));
  const s=slides[current];
  const old=stage.querySelector(".slide");
  if(old&&animate){old.classList.add("exit");setTimeout(()=>mount(),170)}else mount();
  function mount(){
    const slide=document.createElement("article");
    slide.className="slide"+(s.kind==="cover"?" slide-cover":"")+(s.kind==="closing"?" closing":"");
    const head=s.kind==="cover"||s.kind==="closing"?"":`<header class="slide-head reveal"><div><span class="eyebrow">${s.kicker}</span><h2>${s.title}</h2></div></header>`;
    slide.innerHTML=head+s.content;
    stage.replaceChildren(slide);
    requestAnimationFrame(()=>{slide.classList.add("active");animateBars(slide);loadImages(slide)});
    sectionLabel.textContent=s.section;
    progress.style.width=((current+1)/slides.length*100)+"%";
    progressLabel.textContent=String(current+1).padStart(2,"0")+" / "+String(slides.length).padStart(2,"0");
    document.title=(current+1)+". "+s.title+" — MedLink DZ";
    document.querySelector("#prev-btn").disabled=current===0;
    document.querySelector("#next-btn").disabled=current===slides.length-1;
    document.querySelectorAll(".overview-card").forEach((el,i)=>el.classList.toggle("active",i===current));
  }
}
function animateBars(root){root.querySelectorAll(".bar-fill").forEach(el=>{const w=el.dataset.width;requestAnimationFrame(()=>el.style.width=w+"%")})}
function loadImages(root){root.querySelectorAll(".image-slot").forEach(slot=>{const img=slot.querySelector("img");const src=slot.dataset.image;if(!img||!src)return;const reveal=()=>{if(img.naturalWidth&&img.naturalHeight){slot.style.setProperty("--image-ratio",img.naturalWidth+"/"+img.naturalHeight);slot.classList.add("is-loaded")}};img.addEventListener("load",reveal,{once:true});img.addEventListener("error",()=>slot.classList.remove("is-loaded"),{once:true});img.src=src;if(img.complete)reveal()})}
function go(delta){if(locked||overview.classList.contains("hidden")===false)return;const next=Math.max(0,Math.min(slides.length-1,current+delta));if(next===current)return;locked=true;renderSlide(next);setTimeout(()=>locked=false,260)}
function buildOverview(){overviewGrid.innerHTML=slides.map((s,i)=>`<button class="overview-card ${i===current?"active":""}" data-index="${i}"><span>${String(i+1).padStart(2,"0")} · ${s.section}</span><b>${s.title}</b></button>`).join("");overviewGrid.querySelectorAll("button").forEach(b=>b.addEventListener("click",()=>{overview.classList.add("hidden");overview.setAttribute("aria-hidden","true");renderSlide(Number(b.dataset.index))}))}
function toggleOverview(force){const open=typeof force==="boolean"?force:overview.classList.contains("hidden");overview.classList.toggle("hidden",!open);overview.setAttribute("aria-hidden",String(!open))}
document.querySelector("#prev-btn").addEventListener("click",()=>go(-1));
document.querySelector("#next-btn").addEventListener("click",()=>go(1));
document.querySelector("#overview-btn").addEventListener("click",()=>toggleOverview());
document.querySelector("#close-overview").addEventListener("click",()=>toggleOverview(false));
document.querySelector("#fullscreen-btn").addEventListener("click",()=>document.fullscreenElement?document.exitFullscreen():document.documentElement.requestFullscreen?.());
document.addEventListener("keydown",e=>{
 if(e.key==="Escape"){toggleOverview(false);document.querySelector("#help").classList.add("hidden");return}
 if(!overview.classList.contains("hidden"))return;
 if(["ArrowRight"," ","PageDown"].includes(e.key)){e.preventDefault();go(1)}
 if(["ArrowLeft","PageUp"].includes(e.key)){e.preventDefault();go(-1)}
 if(e.key==="Home"){renderSlide(0)}
 if(e.key==="End"){renderSlide(slides.length-1)}
 if(e.key.toLowerCase()==="f"){document.fullscreenElement?document.exitFullscreen():document.documentElement.requestFullscreen?.()}
 if(e.key.toLowerCase()==="g"){toggleOverview()}
 if(e.key==="?"||e.key==="/")document.querySelector("#help").classList.toggle("hidden");
});
document.querySelector("#close-help").addEventListener("click",()=>document.querySelector("#help").classList.add("hidden"));
let touchX=0;
stage.addEventListener("touchstart",e=>touchX=e.changedTouches[0].screenX,{passive:true});
stage.addEventListener("touchend",e=>{const dx=e.changedTouches[0].screenX-touchX;if(Math.abs(dx)>70)go(dx<0?1:-1)},{passive:true});
buildOverview();renderSlide(0,false);

// Lightweight ambient particle field (2D canvas).
const canvas=document.querySelector("#particle-field"),ctx=canvas.getContext("2d");
let particles=[],cw=0,ch=0,raf;
function resizeCanvas(){const dpr=Math.min(devicePixelRatio||1,2);cw=canvas.clientWidth;ch=canvas.clientHeight;canvas.width=cw*dpr;canvas.height=ch*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);particles=Array.from({length:Math.min(75,Math.floor(cw*ch/18000))},()=>({x:Math.random()*cw,y:Math.random()*ch,vx:(Math.random()-.5)*.18,vy:(Math.random()-.5)*.18,r:Math.random()*1.4+.4}))}
function drawParticles(){ctx.clearRect(0,0,cw,ch);for(let i=0;i<particles.length;i++){const p=particles[i];p.x+=p.vx;p.y+=p.vy;if(p.x<0||p.x>cw)p.vx*=-1;if(p.y<0||p.y>ch)p.vy*=-1;ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,Math.PI*2);ctx.fillStyle="rgba(125,226,211,.42)";ctx.fill();for(let j=i+1;j<particles.length;j++){const q=particles[j],dx=p.x-q.x,dy=p.y-q.y,d=Math.hypot(dx,dy);if(d<105){ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(q.x,q.y);ctx.strokeStyle="rgba(91,185,183,"+(1-d/105)*.12+")";ctx.stroke()}}}raf=requestAnimationFrame(drawParticles)}
resizeCanvas();drawParticles();window.addEventListener("resize",resizeCanvas);

// Three.js WebGL hero object: gracefully falls back to CSS orbit if WebGL is unavailable.
(async()=>{try{
 const THREE = await import("three");
 const host=document.createElement("div");host.className="three-host";document.querySelector("#deck").appendChild(host);
 const renderer=new THREE.WebGLRenderer({alpha:true,antialias:true,powerPreference:"low-power"});renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));renderer.setSize(host.clientWidth||innerWidth,host.clientHeight||innerHeight);host.appendChild(renderer.domElement);
 const scene=new THREE.Scene(),camera=new THREE.PerspectiveCamera(38,(host.clientWidth||innerWidth)/(host.clientHeight||innerHeight),.1,100);camera.position.z=7;
 const group=new THREE.Group();scene.add(group);
 const geometry=new THREE.IcosahedronGeometry(1.45,2),material=new THREE.MeshStandardMaterial({color:0x39cdbb,metalness:.72,roughness:.24,wireframe:true,transparent:true,opacity:.35});
 const mesh=new THREE.Mesh(geometry,material);group.add(mesh);
 const ring=new THREE.Mesh(new THREE.TorusGeometry(2.05,.008,8,180),new THREE.MeshBasicMaterial({color:0x66d9ca,transparent:true,opacity:.45}));ring.rotation.x=1.1;group.add(ring);
 scene.add(new THREE.AmbientLight(0xffffff,.7));const light=new THREE.PointLight(0x52e2ce,4,20);light.position.set(2,3,4);scene.add(light);
 let running=true;const clock=new THREE.Clock();function tick(){if(!running)return;const t=clock.getElapsedTime();group.rotation.y=t*.11;group.rotation.x=Math.sin(t*.22)*.12;mesh.rotation.z=t*.08;renderer.render(scene,camera);requestAnimationFrame(tick)}tick();
 new ResizeObserver(()=>{const w=host.clientWidth||innerWidth,h=host.clientHeight||innerHeight;renderer.setSize(w,h);camera.aspect=w/h;camera.updateProjectionMatrix()}).observe(host);
 document.addEventListener("visibilitychange",()=>{running=!document.hidden;if(running)tick()});
 }catch(e){console.info("WebGL indisponible : animation CSS conservée.")}})();
